questionvariables.text:
/*Defining the question variables*/ 
const1:rand(5)+8; /*constant in the first function*/
const2:rand(5)-8; /*constant in the second function*/
expr1:x=const1+y^2; /*first function*/
expr2:x=const2-y^2; /*second function*/
y_1:rand(5)-8; /*lower limit*/
y_2:rand(5)+8; /*upper limit*/
x_1:rhs(ev(expr1,x,y=y_1)); /*min value of x*/
x_2:rhs(ev(expr2,x,y=y_2)); /*max value of x*/
area:rhs(expr1)-rhs(expr2); 
area_func:int(area,y);

/*Worked out solution*/
graph:plot([rhs(expr1),rhs(expr2)],[y,y_1,y_2]);

/*Model answer*/
ta:int(area,y,y_1,y_2);

feedbackvariables.text:
/*Node 1 checks for correct answer*/
/*Node 2 mistake:Integrating the indefinite integral without the limits*/
mistake_2:int(area,y);
/*Node 3 mistake:Interchanging the limits of integration, however, with the correct definite integral.*/
mistake_3:int(area,y,y_2,y_1);
